def show(x, depth=0):
    p = '  '*depth
    if isinstance(x, dict):
        for k,v in x.items():
            print(f'{p}{k}:', end=' ')
            if isinstance(v,(dict,list,tuple)):
                print(); show(v,depth+1)
            else: show(v,0)
